+            1, "Mäkinen", "Joséphine", "josephine@example.com", "Finland", CustomerStatus.ACTIVE);
+
+    @Test
+    void nameMatchingIsAccentInsensitiveAndRequiresEveryTerm() {
+        assertTrue(new CustomerFilter("makinen josephine", Set.of()).matches(CUSTOMER));
+        assertTrue(new CustomerFilter("  JOSEPHINE   makinen ", Set.of()).matches(CUSTOMER));
